'use strict';

function count(r, i, step, x, y) {
    const maxCount = 64;
    const radius2 = 16.0;
    const cr = r + x * step;
    const ci = i + y * step;
    let zr = cr;
    let zi = ci;
    let c = 0;
    while (c < maxCount) {
        const zr2 = zr * zr;
        const zi2 = zi * zi;
        if (zr2 + zi2 > radius2) return c;
        const newZr = zr2 - zi2 + cr;
        zi = 2.0 * zr * zi + ci;
        zr = newZr;
        c++;
    }
